  showResult=function(result){priorShowResult(result);const m=result.summary||{};costDetail.innerHTML=`<b>Simulated costs</b><span>Proportional commission ${money(m.proportional_fees_paid)}</span><span>Fixed commissions ${money(m.fixed_fees_paid)}</span><span>Spread impact ${money(m.spread_cost)}</span><span>Additional slippage ${money(m.slippage_cost)}</span><small>Spread and slippage are included in fill prices. Commissions are charged separately.</small>`;document.querySelectorAll(".terminal-status").forEach(el=>el.textContent="STUDENT PAPER RESEARCH · NO REAL ORDERS");if(result.evaluation){const range=document.createElement("p");range.className="hint";range.textContent=`Actual portfolio evaluation: ${result.evaluation.start.slice(0,10)} to ${result.evaluation.end.slice(0,10)}, ${result.evaluation.bars} bars. ${result.evaluation.note}`;costDetail.append(range);}};
  state.ready=(async()=>{const boot=await api("/api/bootstrap");if(!token)token=boot.token;const profileReply=boot.execution_profiles||boot.cost_scenarios||await api("/api/execution/profiles");state.profiles=Array.isArray(profileReply)?profileReply:(profileReply.profiles||[]);$("setup-profile").innerHTML='<option value="custom">Custom assumptions</option>'+state.profiles.map(profile=>`<option value="${escapeHTML(profile.id)}">${escapeHTML(profile.name)}</option>`).join("");if(wb.info)renderInterpretation(wb.info);setValue("setup-cash",$("cash").value);setValue("setup-fee",Number($("fee").value)/100);setValue("setup-slippage",Number($("slippage").value)/100);setValue("setup-bar-seconds",$("bar-seconds").value);refreshData();go(1);})().catch(error=>{message(`The guided studio could not finish loading. ${error.message}`,true);});
  updateFields(false);refreshData();syncControls();showStudio();
